240:                 // Check if text starts with or contains numbers e.g. "98%", "3-6", "30-60", "70%+", "10,000+"
241:                 const match = text.match(/^(\d+(?:,\d+)?)/);
242:                 if (match && !text.includes('–') && !text.includes('-')) {
243:                     const num = parseInt(match[1].replace(/,/g, ''), 10);
244:                     if (num > 0) {
