259:             const prefix = el.getAttribute('data-prefix') || '';
260:             const suffix = el.getAttribute('data-suffix') || '';
261:             const duration = 1600; // ms
262:             const startTime = performance.now();
263: 
264:             function easeOutExpo(x) {
265:                 return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
266:             }
267: 
268:             function updateCounter(currentTime) {
269:                 const elapsed = currentTime - startTime;
270:                 const progress = Math.min(elapsed / duration, 1);
271:                 const currentVal = Math.floor(easeOutExpo(progress) * target);
272: 
273:                 el.textContent = `${prefix}${currentVal.toLocaleString()}${suffix}`;
274: 
275:                 if (progress < 1) {
276:                     requestAnimationFrame(updateCounter);
