const express = require("express");
const zlib = require("zlib");
const path = require("path");
const http = require("http");

const app = express();
app.use((req, res, next) => {
    console.log("Middleware called for path:", req.path);
    const ae = req.headers["accept-encoding"] || "";
    if (req.method !== "GET" || !/\bgzip\b/.test(ae)) return next();
    if (!/\.(html?|css|js|mjs|json|svg|xml|txt|map|webmanifest)$/i.test(req.path)) return next();

    const rawWrite = res.write.bind(res);
    const rawEnd   = res.end.bind(res);
    const chunks   = [];
    let finished   = false;

    res.write = function (chunk, enc, cb) {
        if (chunk) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, enc));
        if (typeof cb === "function") cb();
        return true;
    };
    res.end = function (chunk, enc, cb) {
        if (finished) return;
        finished = true;
        if (typeof chunk === "function") { cb = chunk; chunk = null; enc = null; }
        else if (typeof enc === "function") { cb = enc; enc = null; }
        if (chunk) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, enc));
        const body = Buffer.concat(chunks);
        console.log("res.end called! body length:", body.length, "headersSent:", res.headersSent);

        if (res.statusCode !== 200 || body.length === 0 || res.getHeader("Content-Encoding")) {
            console.log("Skipping gzip:", { statusCode: res.statusCode, len: body.length, ce: res.getHeader("Content-Encoding") });
            if (body.length) { res.setHeader("Content-Length", body.length); rawWrite(body); }
            return rawEnd(cb);
        }
        zlib.gzip(body, (err, zipped) => {
            console.log("gzip finished, zipped len:", zipped ? zipped.length : err);
            if (err) { res.setHeader("Content-Length", body.length); rawWrite(body); return rawEnd(cb); }
            try {
                res.setHeader("Content-Encoding", "gzip");
                res.setHeader("Vary", "Accept-Encoding");
                res.setHeader("Content-Length", zipped.length);
                rawWrite(zipped);
                rawEnd(cb);
            } catch(e) {
                console.error("Error setting headers:", e.message);
                rawWrite(body);
                rawEnd(cb);
            }
        });
    };
    next();
});

app.use(express.static(path.join(__dirname, "frontend")));

const server = app.listen(3099, () => {
    http.get("http://localhost:3099/css/bundle-home.min.css", { headers: { "Accept-Encoding": "gzip" } }, (res) => {
        console.log("Response headers:", res.headers);
        server.close();
    });
});
